/**
 * Brand assets per product host (WP22-10, ADR-0016). Pure: shared by the root layout (`generateMetadata`), client
 * components that draw the mark for the current host, and the test that checks every file below exists in `public/`.
 *
 * The files are GENERATED by `brand/scripts/build.mjs` (group `web`); the manifests are hand-kept, one per host.
 * The family mark (no suffix) serves the suite root and every legacy host (run.app, localhost, LAN).
 */
import type { BrandId } from "@mmo/ui";
import type { HostKind } from "./products";

/** The marks a web host can carry (`dj` is the route key of MixAI Decks, ADR-0014). */
export type HostBrandId = Extract<BrandId, "mark" | "tv" | "music" | "studio" | "decks" | "live">;

const BRAND: Record<HostKind, HostBrandId> = {
    suite: "mark",
    legacy: "mark",
    tv: "tv",
    music: "music",
    studio: "studio",
    dj: "decks",
    live: "live",
};

const NAME: Record<HostBrandId, string> = {
    mark: "MixAI",
    tv: "MixAI TV",
    music: "MixAI Music",
    studio: "MixAI Studio",
    decks: "MixAI Decks",
    live: "MixAI Live",
};

export interface HostBrandAssets {
    id: HostBrandId;
    /** Product name, always "MixAI <Product>" (the suite root is "MixAI"). */
    name: string;
    manifest: string;
    /** SVG favicon with its own light/dark switch. */
    iconSvg: string;
    /** Shared 32 px `.ico` (family mark) for browsers without SVG favicons. */
    favicon: string;
    /** 180 px, opaque. */
    appleTouchIcon: string;
    /** 1200 × 630. */
    ogImage: string;
}

/** Which mark a host shows (`<BrandMark product>`). */
export function hostBrand(kind: HostKind): HostBrandId {
    return BRAND[kind];
}

export function hostBrandAssets(kind: HostKind): HostBrandAssets {
    const id = BRAND[kind];
    const suffix = id === "mark" ? "" : `-${id}`;
    return {
        id,
        name: NAME[id],
        manifest: kind === "legacy" ? "/manifest.webmanifest" : `/manifest-${id === "mark" ? "suite" : id}.webmanifest`,
        iconSvg: `/icon${suffix}.svg`,
        favicon: "/favicon.ico",
        appleTouchIcon: `/apple-touch-icon${suffix}.png`,
        ogImage: `/og-image${suffix}.png`,
    };
}
